#!/usr/bin/env bash
set -euo pipefail
mkdir -p /tmp/wifi_guard_ai/$(dirname 'pubspec.yaml')
echo '' | base64 -d > /tmp/wifi_guard_ai/'pubspec.yaml'
mkdir -p /tmp/wifi_guard_ai/$(dirname 'android/app/build.gradle.kts')
echo '' | base64 -d > /tmp/wifi_guard_ai/'android/app/build.gradle.kts'
mkdir -p /tmp/wifi_guard_ai/$(dirname 'android/app/src/main/kotlin/com/example/wifiguardai/security/DnsMessageParser.kt')
echo '' | base64 -d > /tmp/wifi_guard_ai/'android/app/src/main/kotlin/com/example/wifiguardai/security/DnsMessageParser.kt'
mkdir -p /tmp/wifi_guard_ai/$(dirname 'android/app/src/main/kotlin/com/example/wifiguardai/security/NetworkStateMonitor.kt')
echo '' | base64 -d > /tmp/wifi_guard_ai/'android/app/src/main/kotlin/com/example/wifiguardai/security/NetworkStateMonitor.kt'
mkdir -p /tmp/wifi_guard_ai/$(dirname 'android/app/src/main/kotlin/com/example/wifiguardai/security/TlsProbe.kt')
echo '' | base64 -d > /tmp/wifi_guard_ai/'android/app/src/main/kotlin/com/example/wifiguardai/security/TlsProbe.kt'
